tool_input.command:
cat > /tmp/shot.mjs << 'EOF'
import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:5173/settings/template-clause-library');
await page.click('text=Clause Library');
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/clause_tab.png' });

await page.click('text=+ New Template');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/new_template.png' });
await page.click('text=Discard');
await page.waitForTimeout(300);

await page.click('text=+ New Clause');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/new_clause.png' });
await page.click('text=Discard');
await page.waitForTimeout(300);

await page.click('text=Templates');
await page.waitForTimeout(300);
await page.click('text=Version History >> nth=0');
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/version_history.png' });

await browser.close();
EOF
node /tmp/shot.mjs
